// Eingabe pruefen, bevor irgendetwas passiert. Der Aufrufer hat
// vorher entschieden, dass etwas zu senden ist. Kommt hier nichts
// an, ist das ein Programmierfehler und kein Normalfall. Deshalb
// wird geworfen und nicht still zurueckgegeben.
const a = $('Aufruf').first().json ?? {};

const ids = (Array.isArray(a.doc_ids) ? a.doc_ids : [a.doc_ids])
  .filter(v => v !== null && v !== undefined && String(v).trim() !== '')
  .map(Number);

if (!ids.length) throw new Error('sub-sevdesk-versand ohne Belege aufgerufen: doc_ids ist leer. Der Aufrufer haette gar nicht rufen duerfen.');
if (ids.some(n => !Number.isFinite(n))) throw new Error('doc_ids enthaelt etwas, das keine Zahl ist: ' + JSON.stringify(a.doc_ids));
if (String(a.empfaenger ?? '').indexOf('@') === -1) throw new Error('Keine sevDesk-Empfaengeradresse uebergeben. In der n8n-Oberflaeche unter "Data Tables" den Schluessel mail_sevdesk setzen.');
if (String(a.absender ?? '').indexOf('@') === -1) throw new Error('Keine Absenderadresse uebergeben: pw_config, Schluessel mail_sevdesk_absender. sevDesk nimmt nur Mail von hinterlegten Absendern an.');
if (!Number.isFinite(Number(a.tag_gesendet_id))) throw new Error('tag_gesendet_id fehlt; der Aufrufer muss die Paperless-ID von "Steuer-gesendet" mitgeben.');

return [{ json: {
  doc_ids: ids,
  id_liste: ids.join(','),
  paperless_url: String(a.paperless_url).replace(/\/+$/, ''),
  empfaenger: a.empfaenger,
  absender: a.absender,
  dateiname_quelle: a.dateiname_quelle || 'titel',
  zeitraum: a.zeitraum || '',
  tag_gesendet_id: Number(a.tag_gesendet_id)
} }];

// Pro Beleg entscheiden, ob Original oder Archiv-PDF an sevDesk geht.
// Die sevDesk-Autobox akzeptiert PDF/TIF/TIFF. Ist das Original schon
// eines davon, geht es unveraendert raus, wichtig etwa bei
// ZUGFeRD-PDFs, deren XML-Anhang beim Umwandeln verloren ginge.
// Sonst gilt die Archiv-Version, die in Paperless immer PDF ist.
const auftrag = $('Auftrag prüfen').first().json;
const docs = $json.results || [];
const okExt = ['.pdf', '.tif', '.tiff'];

// Stille Datenverluste sichtbar machen: page_size deckelt bei 250, und
// eine geloeschte ID kaeme hier einfach nicht zurueck. Beides waere
// ein nicht gesendeter Beleg, den niemand vermisst.
if (docs.length !== auftrag.doc_ids.length) {
  const da = docs.map(d => d.id);
  const fehlt = auftrag.doc_ids.filter(id => !da.includes(id));
  throw new Error('Paperless lieferte ' + docs.length + ' von ' + auftrag.doc_ids.length + ' angeforderten Belegen. Fehlend: ' + fehlt.join(', ') + '. Entweder wurden sie zwischenzeitlich geloescht, oder es waren mehr als 250 auf einmal.');
}

return docs.map(d => {
  const name = (d.original_file_name || '').toLowerCase();
  const useOriginal = okExt.some(ext => name.endsWith(ext));
  return { json: {
    id: d.id,
    title: d.title || ('Dokument ' + d.id),
    created: d.created,
    original_file_name: d.original_file_name || null,
    use_original: useOriginal,
    download_url: auftrag.paperless_url + '/api/documents/' + d.id + '/download/' + (useOriginal ? '?original=true' : '')
  }};
});

// Anhangs-Dateiname setzen, sonst hiesse jede Datei 'data.pdf'.
const doc = $('Loop über Belege').item.json;
const auftrag = $('Auftrag prüfen').first().json;
const item = $input.item;

if (!item.binary || !item.binary.data) {
  throw new Error('Kein Binaerinhalt fuer Dokument ' + doc.id + ': Download fehlgeschlagen?');
}

// Endung: beim Original vom Originalnamen uebernehmen,
// die Archiv-Version ist immer PDF.
const orig = doc.original_file_name || '';
const dotPos = orig.lastIndexOf('.');
const ext = (doc.use_original && dotPos > 0) ? orig.slice(dotPos).toLowerCase() : '.pdf';

// Basisname: Paperless-Titel (Standard) oder Original-Dateiname ohne
// Endung; letzteres sind oft Scanner-Namen wie Scan_00382.pdf.
let base;
if (auftrag.dateiname_quelle === 'original' && orig) {
  base = dotPos > 0 ? orig.slice(0, dotPos) : orig;
} else {
  base = doc.title || ('Beleg-' + doc.id);
}

// Fuer Datei- und Mailsysteme problematische Zeichen entschaerfen.
base = base.replace(/[\\/:*?"<>|\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
if (!base) base = 'Beleg-' + doc.id;

item.binary.data.fileName = base + ext;
return item;

// Ergebnis an den Aufrufer. Der Monatslauf baut daraus seinen
// Bericht, der Sofortversand quittiert danach nur noch das
// Kommando-Tag. Beide sehen dieselbe Struktur, deshalb ist ihnen
// egal, welcher Versand-Sub gelaufen ist.
const docs = $('Dokumentliste aufbauen').all().map(i => i.json);
return [{ json: {
  status: 'gesendet',
  kanal: 'sevDesk',
  anzahl: docs.length,
  doc_ids: docs.map(d => d.id),
  belege: docs.map(d => ({ id: d.id, titel: d.title, created: d.created, original: d.use_original }))
} }];
